solutionReferences.cpp:
#include <iostream>

int main() {
    int temperatura = 35;
    if (temperatura > 30) {
        std::cout << "Hace calor" << "\n";
    } else {
        std::cout << "Temperatura agradable" << "\n";
    }
    return 0;
}
